    if (Compress(0, 0, 0, out, 0, 0) != 1 || out[0] != 0x80) { std::printf("00f3a2e0_TEST FAIL\n"); return 1; }
    std::printf("00f3a2e0_TEST PASS\n");
    return 0;
}
